inline double normalize_directional_shadow_pcf_radius(double radius) {
  if (!std::isfinite(radius)) {
    return 0.0;
  }
  return flight::minimum(flight::types::max_directional_shadow_pcf_radius, flight::maximum(0.0, std::floor(radius)));
}

